# our updated program here
import time
import numpy as np
import math
import random
from collections import defaultdict, deque

class CVRPSolver:
    def __init__(self, coordinates: np.ndarray, distance_matrix: np.ndarray, demands: list, vehicle_capacity: int):
        """
        Initialize the CVRP solver.

        Args:
            coordinates: Numpy array of shape (n, 2) containing the (x, y) coordinates of each node, including the depot.
            distance_matrix: Numpy array of shape (n, n) containing pairwise distances between nodes.
            demands: List of integers representing the demand of each node (first node is typically the depot with zero demand).
            vehicle_capacity: Integer representing the maximum capacity of each vehicle.
        """
        self.coordinates = np.asarray(coordinates)
        self.distance_matrix = np.asarray(distance_matrix)
        self.demands = list(demands)
        self.vehicle_capacity = vehicle_capacity
        self.n = len(self.coordinates)
        # indices of customers (excluding depot 0)
        self.customers = list(range(1, self.n))
        # random seed for determinism
        random.seed(0)
        np.random.seed(0)

    # ---------------- Helper internal methods ----------------

    def _initial_k(self):
        total_demand = sum(self.demands[1:])
        # lower bound on number of vehicles
        k = max(1, math.ceil(total_demand / self.vehicle_capacity))
        # allow a few extra partitions to enable adaptive splitting
        return min(len(self.customers), k + max(0, k // 4))

    def _kmeans(self, k, max_iter=20):
        # Simple k-means on coordinates of customers (not depot)
        pts = self.coordinates[self.customers]
        m = len(pts)
        if k <= 0 or m == 0:
            return {i: [] for i in range(k)}
        # initialize centers by sampling
        centers_idx = np.random.choice(m, size=min(k, m), replace=False)
        centers = pts[centers_idx].astype(float)
        labels = np.zeros(m, dtype=int)
        for _ in range(max_iter):
            # assign
            dists = np.linalg.norm(pts[:, None, :] - centers[None, :, :], axis=2)
            new_labels = np.argmin(dists, axis=1)
            if np.array_equal(new_labels, labels):
                break
            labels = new_labels
            # update centers
            for j in range(len(centers)):
                assigned = pts[labels == j]
                if len(assigned) > 0:
                    centers[j] = assigned.mean(axis=0)
                else:
                    # reinitialize empty cluster
                    centers[j] = pts[np.random.randint(0, m)]
        # build partition mapping: cluster index -> list of global node indices
        partitions = defaultdict(list)
        for idx_cust, lab in enumerate(labels):
            partitions[lab].append(self.customers[idx_cust])
        # if some clusters empty, remove them
        parts = [part for part in partitions.values() if len(part) > 0]
        if len(parts) == 0:
            parts = [self.customers[:]]
        # renumbered partitions
        return {i: parts[i] for i in range(len(parts))}

    def _build_subproblem(self, partition_nodes, interface_nodes):
        # Submodel is simply list of nodes (including depot 0) and marked interfaces
        nodes = [0] + partition_nodes[:]  # depot first
        return {'nodes': nodes, 'interfaces': set(interface_nodes)}

    def _held_karp_tsp(self, nodes):
        """
        Exact Held-Karp TSP solver for a small set of nodes (including depot 0).
        Returns a tour (list of global node indices) starting and ending at depot 0.
        Falls back to a faster heuristic for larger instances.

        nodes: iterable of global node indices. Depot (0) may be present anywhere or omitted.
        """
        # Normalize nodes: unique, ensure depot 0 is present and at index 0
        seen = set()
        subnodes = []
        for v in nodes:
            if v in seen:
                continue
            seen.add(v)
            subnodes.append(v)
        if 0 not in seen:
            subnodes.insert(0, 0)
        else:
            # move depot to front if not already
            if subnodes[0] != 0:
                subnodes.remove(0)
                subnodes.insert(0, 0)

        m = len(subnodes)
        # trivial cases
        if m == 1:
            # only depot
            return [0, 0]
        if m == 2:
            # depot -> single customer -> depot
            return [0, subnodes[1], 0]

        # For larger sets fall back to heuristic to avoid exponential blowup
        if m > 13:  # keep threshold slightly conservative (original used 12)
            return self._tsp_greedy_2opt(subnodes)

        # Build a small Python-native distance matrix for speed in inner loops
        subd_np = self.distance_matrix[np.ix_(subnodes, subnodes)]
        sd = subd_np.tolist()  # sd[i][j] gives distance from subnodes[i] to subnodes[j]

        n_cust = m - 1  # number of customers (excluding depot at sub-index 0)
        nmask = 1 << n_cust
        inf = float('inf')

        # Precompute bit lists: for each mask store indices of set bits (0..n_cust-1)
        bit_lists = [[] for _ in range(nmask)]
        for mask in range(1, nmask):
            mm = mask
            bl = []
            while mm:
                low = mm & -mm
                b = low.bit_length() - 1
                bl.append(b)
                mm -= low
            bit_lists[mask] = bl

        # DP tables: dp[mask][j] = best cost to start at depot, visit mask and end at customer j
        dp = [[inf] * n_cust for _ in range(nmask)]
        parent = [[-1] * n_cust for _ in range(nmask)]

        # Initialize single-customer masks
        for j in range(n_cust):
            mask = 1 << j
            dp[mask][j] = sd[0][j + 1]
            parent[mask][j] = -1

        # Fill DP
        for mask in range(1, nmask):
            # skip singletons (already initialized)
            if mask & (mask - 1) == 0:
                continue
            bits = bit_lists[mask]
            for j in bits:
                prev_mask = mask ^ (1 << j)
                best_cost = inf
                best_prev = -1
                # iterate possible previous end nodes k in prev_mask
                for k in bit_lists[prev_mask]:
                    # cost to go from k -> j
                    cost = dp[prev_mask][k] + sd[k + 1][j + 1]
                    if cost < best_cost:
                        best_cost = cost
                        best_prev = k
                dp[mask][j] = best_cost
                parent[mask][j] = best_prev

        # Close tour: pick last customer minimizing dp[full_mask][k] + dist(k, depot)
        full_mask = nmask - 1
        best_cost = inf
        last = -1
        for k in range(n_cust):
            cost = dp[full_mask][k] + sd[k + 1][0]
            if cost < best_cost:
                best_cost = cost
                last = k

        # If no feasible tour found (shouldn't happen), fallback to simple route
        if last == -1 or best_cost == inf:
            return [0] + subnodes[1:] + [0]

        # Reconstruct path of customers (global indices)
        seq = []
        mask = full_mask
        k = last
        while k != -1:
            seq.append(subnodes[k + 1])
            prev = parent[mask][k]
            mask ^= (1 << k)
            k = prev
        seq.reverse()

        path = [0] + seq + [0]
        return path

    def _combinations(self, arr, r):
        # simple combinations generator returning tuples of r elements from arr
        from itertools import combinations
        return combinations(arr, r)

    def _tsp_greedy_2opt(self, nodes):
        # greedy nearest neighbor starting at depot 0
        unvisited = set(nodes)
        tour = [0]
        unvisited.remove(0)
        current = 0
        while unvisited:
            # pick nearest unvisited
            nearest = min(unvisited, key=lambda x: self.distance_matrix[current, x])
            tour.append(nearest)
            unvisited.remove(nearest)
            current = nearest
        tour.append(0)
        # simple 2-opt improvement
        improved = True
        max_iter = 50
        it = 0
        while improved and it < max_iter:
            improved = False
            it += 1
            for i in range(1, len(tour) - 2):
                for j in range(i + 1, len(tour) - 1):
                    a, b = tour[i - 1], tour[i]
                    c, d = tour[j], tour[j + 1]
                    delta = (self.distance_matrix[a, c] + self.distance_matrix[b, d]) - (self.distance_matrix[a, b] + self.distance_matrix[c, d])
                    if delta < -1e-9:
                        tour[i:j + 1] = reversed(tour[i:j + 1])
                        improved = True
            if not improved:
                break
        return tour

    def _split_tour_by_capacity(self, tour):
        # tour is list of nodes starting and ending at depot 0; split into feasible routes by following order
        routes = []
        current_route = [0]
        cap = 0
        for node in tour[1:]:
            if node == 0:
                if len(current_route) > 1:
                    current_route.append(0)
                    routes.append(current_route)
                current_route = [0]
                cap = 0
            else:
                d = self.demands[node]
                if cap + d > self.vehicle_capacity:
                    # close previous if has customers
                    if len(current_route) > 1:
                        current_route.append(0)
                        routes.append(current_route)
                    current_route = [0, node]
                    cap = d
                else:
                    current_route.append(node)
                    cap += d
        if len(current_route) > 1:
            if current_route[-1] != 0:
                current_route.append(0)
            routes.append(current_route)
        # Ensure every route valid
        valid_routes = []
        for r in routes:
            # check capacity
            s = sum(self.demands[i] for i in r if i != 0)
            if s <= self.vehicle_capacity:
                valid_routes.append(r)
            else:
                # if one route exceeds capacity (rare), force split greedily
                tmp = []
                cur = [0]
                curcap = 0
                for v in r[1:]:
                    if v == 0:
                        if len(cur) > 1:
                            cur.append(0); tmp.append(cur)
                        cur = [0]; curcap = 0
                    else:
                        if curcap + self.demands[v] > self.vehicle_capacity:
                            if len(cur) > 1:
                                cur.append(0); tmp.append(cur)
                            cur = [0, v]; curcap = self.demands[v]
                        else:
                            cur.append(v); curcap += self.demands[v]
                if len(cur) > 1:
                    if cur[-1] != 0: cur.append(0)
                    tmp.append(cur)
                valid_routes.extend(tmp)
        return valid_routes

    def _solve_subproblem_exactly(self, submodel, subsolver_time):
        # submodel contains nodes: [0, ...customers...]
        # For small partitions use Held-Karp TSP then split by capacity
        nodes = submodel['nodes']
        # If only depot no customers
        if len(nodes) <= 1:
            return []
        tour = self._held_karp_tsp(nodes)
        routes = self._split_tour_by_capacity(tour)
        return routes

    def _merge_subsolutions(self, subsolutions, consensus):
        # subsolutions: dict part -> list of routes (each route is list nodes)
        # consensus not used heavily; simply combine routes
        merged = []
        for p in sorted(subsolutions.keys()):
            for r in subsolutions[p]:
                merged.append(r[:])
        # sort routes by first customer proximity to depot for determinism
        merged.sort(key=lambda rt: (len(rt), rt[1] if len(rt) > 1 else 0))
        # flatten into single list with depot separators
        flat = []
        for r in merged:
            if not flat or flat[-1] != 0:
                flat.append(0)
            for v in r[1:]:
                flat.append(v)
        if not flat or flat[-1] != 0:
            flat.append(0)
        return flat

    def _evaluate_solution(self, flat_solution):
        # compute total distance; ensure route boundaries at zeros
        if flat_solution is None or len(flat_solution) == 0:
            return math.inf
        total = 0.0
        for i in range(len(flat_solution) - 1):
            a = flat_solution[i]
            b = flat_solution[i + 1]
            total += self.distance_matrix[a, b]
        # penalize infeasibilities heavily
        # check coverage
        visited = [0] * self.n
        for v in flat_solution:
            if 0 <= v < self.n:
                visited[v] += 1
        # each customer must be visited exactly once
        for i in range(1, self.n):
            if visited[i] != 1:
                total += 1e6 + abs(visited[i] - 1) * 1e5
        # capacity checks per route
        cap = 0
        for v in flat_solution[1:]:
            if v == 0:
                cap = 0
            else:
                cap += self.demands[v]
                if cap > self.vehicle_capacity:
                    total += 1e6 + (cap - self.vehicle_capacity) * 1e5
        return total

    def _repair_and_validate(self, flat_solution):
        # Ensure each customer visited exactly once and capacity respected.
        # Strategy: construct routes from flat_solution, remove duplicates, collect missing, then insert missing into nearest feasible routes
        if flat_solution is None or len(flat_solution) == 0:
            return [0, 0]
        # build initial routes
        routes = []
        cur = [0]
        for v in flat_solution[1:]:
            if v == 0:
                if len(cur) > 1:
                    cur.append(0)
                    routes.append(cur)
                cur = [0]
            else:
                cur.append(v)
        if len(cur) > 1:
            if cur[-1] != 0:
                cur.append(0)
            routes.append(cur)
        # track visits
        seen = {}
        for ri, r in enumerate(routes):
            for v in r:
                if v != 0:
                    if v not in seen:
                        seen[v] = ri
                    else:
                        # duplicate: mark for removal later
                        seen[v] = -1  # -1 marks duplicate
        # remove duplicates keeping first occurrence
        assigned = set()
        new_routes = []
        for r in routes:
            newr = [0]
            for v in r[1:]:
                if v == 0:
                    continue
                if v not in assigned:
                    assigned.add(v)
                    newr.append(v)
            if len(newr) > 1:
                newr.append(0)
                new_routes.append(newr)
        routes = new_routes
        # find missing customers
        missing = [i for i in range(1, self.n) if i not in assigned]
        # Try to insert missing into nearest route with capacity
        for cust in missing:
            best_r = None
            best_pos = None
            best_inc = math.inf
            demand = self.demands[cust]
            for ri, r in enumerate(routes):
                load = sum(self.demands[v] for v in r if v != 0)
                if load + demand > self.vehicle_capacity:
                    continue
                # find best insertion position minimizing added distance
                for pos in range(1, len(r)):  # insert before r[pos] (pos can be len(r)-1 which is 0)
                    a = r[pos - 1]
                    b = r[pos]
                    inc = self.distance_matrix[a, cust] + self.distance_matrix[cust, b] - self.distance_matrix[a, b]
                    if inc < best_inc:
                        best_inc = inc
                        best_r = ri
                        best_pos = pos
            if best_r is not None:
                routes[best_r].insert(best_pos, cust)
            else:
                # create a new route if possible
                if demand <= self.vehicle_capacity:
                    routes.append([0, cust, 0])
                else:
                    # cannot satisfy demand -> leave removal; will be penalized
                    routes.append([0, cust, 0])
        # Finally, ensure no route exceeds capacity; if it does, split greedily
        final_routes = []
        for r in routes:
            load = 0
            cur = [0]
            for v in r[1:]:
                if v == 0:
                    if len(cur) > 1:
                        cur.append(0); final_routes.append(cur)
                    cur = [0]; load = 0
                else:
                    if load + self.demands[v] > self.vehicle_capacity:
                        if len(cur) > 1:
                            cur.append(0); final_routes.append(cur)
                        cur = [0, v]; load = self.demands[v]
                    else:
                        cur.append(v); load += self.demands[v]
            if len(cur) > 1:
                if cur[-1] != 0: cur.append(0)
                final_routes.append(cur)
        # Build flat
        flat = []
        for r in final_routes:
            if not flat or flat[-1] != 0:
                flat.append(0)
            for v in r[1:]:
                flat.append(v)
        if not flat or flat[-1] != 0:
            flat.append(0)
        return flat

    def _update_interfaces(self, partitions, subsolutions):
        # define interface nodes as customers close to partition borders: those served in routes that contain customers from other partitions nearby
        # simple heuristic: compute centroid of each partition and mark nodes whose distance to nearest non-own centroid is within 1.2x of own centroid distance
        k = len(partitions)
        centroids = {}
        for p, nodes in partitions.items():
            if nodes:
                centroids[p] = np.mean(self.coordinates[nodes], axis=0)
            else:
                centroids[p] = np.zeros(2)
        interface = {p: set() for p in partitions}
        for p, nodes in partitions.items():
            for v in nodes:
                own_dist = np.linalg.norm(self.coordinates[v] - centroids[p])
                # find nearest other centroid
                min_other = math.inf
                for q, c in centroids.items():
                    if q == p: continue
                    d = np.linalg.norm(self.coordinates[v] - c)
                    if d < min_other:
                        min_other = d
                if min_other < 1.2 * own_dist + 1e-9:
                    interface[p].add(v)
        # Also include customers at boundaries of routes from subsolutions that are close to other partitions
        return interface

    def _adaptive_repartition(self, partitions, interfaces, subsolutions, params):
        # Recompute k (maybe split overloaded partitions) and re-run kmeans with k adjusted
        part_demands = {p: sum(self.demands[v] for v in nodes) for p, nodes in partitions.items()}
        # compute ideal K
        ideal_k = max(1, math.ceil(sum(self.demands[1:]) / self.vehicle_capacity))
        # if some partitions are heavy, increase k
        heavy = sum(1 for v in part_demands.values() if v > 1.2 * (sum(self.demands[1:]) / max(1, len(partitions))))
        k = max(ideal_k, len(partitions) + heavy)
        # limit k
        k = min(k, len(self.customers))
        new_parts = self._kmeans(k, max_iter=20)
        return new_parts

    # ---------------- Public solver method ----------------

    def solve(self, time_limit: float = 5.0, params: dict = None) -> list:
        """
        Solve the Capacitated Vehicle Routing Problem (CVRP).

        Returns:
            A one-dimensional list of integers representing the sequence of nodes visited by all vehicles.
        """
        if params is None:
            params = {}
        t0 = time.time()
        # encode problem is already in self
        # init interfaces & partitions
        partitions = self._kmeans(self._initial_k(), max_iter=20)
        interfaces = self._update_interfaces(partitions, None)
        best = None
        best_cost = math.inf
        # parameters
        subsolver_time = params.get('subsolver_time', 0.05)
        max_iters = params.get('max_iters', 100)
        iter_count = 0

        # main loop
        while True:
            iter_count += 1
            if time.time() - t0 > time_limit or iter_count > max_iters:
                break
            subsolutions = {}
            # solve each partition
            for p, nodes in partitions.items():
                submodel = self._build_subproblem(nodes, interfaces.get(p, set()))
                routes = self._solve_subproblem_exactly(submodel, subsolver_time)
                subsolutions[p] = routes
            # consensus step: local interface moves to reduce penalties
            # We'll attempt to reassign interface nodes to neighboring partitions greedily
            # Build quick mapping of node->partition
            node_to_part = {}
            for p, nodes in partitions.items():
                for v in nodes:
                    node_to_part[v] = p
            # try moving each interface node to a neighboring partition if improves local evaluation
            improved = True
            attempts = 0
            while improved and attempts < 5:
                improved = False
                attempts += 1
                for p, iface in interfaces.items():
                    for v in list(iface):
                        best_local_cost = None
                        best_target = None
                        current_part = node_to_part.get(v, p)
                        for q in partitions.keys():
                            if q == current_part:
                                continue
                            # simulate removing v from current_part and adding to q
                            part_nodes_current = [x for x in partitions[current_part] if x != v]
                            part_nodes_target = partitions[q] + [v]
                            # quick solve subproblems for these two partitions
                            r1 = self._solve_subproblem_exactly(self._build_subproblem(part_nodes_current, interfaces.get(current_part, set())), subsolver_time)
                            r2 = self._solve_subproblem_exactly(self._build_subproblem(part_nodes_target, interfaces.get(q, set())), subsolver_time)
                            # evaluate combined cost of these two partition routes
                            flat = []
                            for rr in r1 + r2:
                                if not flat or flat[-1] != 0:
                                    flat.append(0)
                                for vv in rr[1:]:
                                    flat.append(vv)
                            if not flat or flat[-1] != 0:
                                flat.append(0)
                            cost = self._evaluate_solution(flat)
                            if best_local_cost is None or cost < best_local_cost:
                                best_local_cost = cost
                                best_target = q
                        # decide move if improves local cost
                        if best_target is not None:
                            # compute current local cost
                            cur_r1 = self._solve_subproblem_exactly(self._build_subproblem([x for x in partitions[current_part]], interfaces.get(current_part, set())), subsolver_time)
                            cur_r2 = self._solve_subproblem_exactly(self._build_subproblem([x for x in partitions[best_target]], interfaces.get(best_target, set())), subsolver_time)
                            cur_flat = []
                            for rr in cur_r1 + cur_r2:
                                if not cur_flat or cur_flat[-1] != 0:
                                    cur_flat.append(0)
                                for vv in rr[1:]:
                                    cur_flat.append(vv)
                            if not cur_flat or cur_flat[-1] != 0:
                                cur_flat.append(0)
                            cur_cost = self._evaluate_solution(cur_flat)
                            if best_local_cost + 1e-9 < cur_cost:
                                # perform move
                                partitions[current_part] = [x for x in partitions[current_part] if x != v]
                                partitions[best_target].append(v)
                                node_to_part[v] = best_target
                                improved = True
                if improved:
                    interfaces = self._update_interfaces(partitions, subsolutions)

            # after consensus, rebuild all subsolutions (reflect changes)
            subsolutions = {}
            for p, nodes in partitions.items():
                submodel = self._build_subproblem(nodes, interfaces.get(p, set()))
                routes = self._solve_subproblem_exactly(submodel, subsolver_time)
                subsolutions[p] = routes

            # merge
            candidate = self._merge_subsolutions(subsolutions, None)
            # repair and validate
            candidate = self._repair_and_validate(candidate)
            # evaluate
            cost = self._evaluate_solution(candidate)
            if cost < best_cost:
                best_cost = cost
                best = candidate[:]
            # update interfaces
            interfaces = self._update_interfaces(partitions, subsolutions)
            # adaptive repartition
            partitions = self._adaptive_repartition(partitions, interfaces, subsolutions, params)

        # If best still None, fallback naive sequential packing
        if best is None:
            solution = [0]
            curcap = 0
            for i in range(1, self.n):
                if curcap + self.demands[i] > self.vehicle_capacity:
                    solution.append(0); curcap = 0
                solution.append(i); curcap += self.demands[i]
            if solution[-1] != 0:
                solution.append(0)
            return solution

        # final ensure validity
        best = self._repair_and_validate(best)
        return best
